(5641733, 817585, 24454, '<td valign="top">Ohhhhh EXCELLENT, Inna!  My favorite kind of photo.  I''m glad you won with this one.  I think your grandma is beautiful.  Such character in those lines.</td>', 'Ohhhhh EXCELLENT, Inna!  My favorite kind of photo.  I''m glad you won with this one.  I think your grandma is beautiful.  Such character in those lines.', '2009-09-09 10:20:30.000000', NULL, 0),
(5641734, 818771, 24454, '<td valign="top">Wow!  THIS is AWESOME!!!  Not just "lines" -- but a frameable work of art as well!  Congratulations on so many levels!</td>', 'Wow!  THIS is AWESOME!!!  Not just "lines" -- but a frameable work of art as well!  Congratulations on so many levels!', '2009-09-09 10:21:29.000000', NULL, 0),
