(5642288, 818778, 91716, '<td valign="top">I really like this picture, i didnt vote so didn''t leave the comment (sorry) but I thinks it''s way better than some of the photos with a higher score. Amazing colors.</td>', 'I really like this picture, i didnt vote so didn''t leave the comment (sorry) but I thinks it''s way better than some of the photos with a higher score. Amazing colors.', '2009-09-09 16:53:28.000000', NULL, 0),
(5642331, 817839, 83313, '<td valign="top">My comments and votes are starting to line up with <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=50695" rel="nofollow" target="_blank">Posthumous</a>. Not sure what that means...</td>', 'My comments and votes are starting to line up with  Posthumous. Not sure what that means...', '2009-09-09 17:29:45.000000', NULL, 0),
