INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5642420, 818295, 90495, '<td valign="top">This is a really cool image that should have finished above 6, easy. Don''t know why you got all those 4 and below scores.</td>', 'This is a really cool image that should have finished above 6, easy. Don''t know why you got all those 4 and below scores.', '2009-09-09 19:25:43.000000', NULL, 0),
(5642431, 818617, 4793, '<td valign="top">Beautiful shot</td>', 'Beautiful shot', '2009-09-09 19:48:42.000000', NULL, 0),
(5642432, 817585, 4793, '<td valign="top">Beautiful work</td>', 'Beautiful work', '2009-09-09 19:49:36.000000', NULL, 0),
(5642486, 817374, 105393, '<td valign="top">Yeah, this was a pretty dark image to begin with and I didn''t want to mess with it <i>too</i> much in Photoshop. It''s my first entry here, and I knew it wouldn''t work as soon as I saw how dark the thumbnail turned out. Live and learn. :-) Flash might have been cool, yeah. Thanks for the feedback.</td>', 'Yeah, this was a pretty dark image to begin with and I didn''t want to mess with it too much in Photoshop. It''s my first entry here, and I knew it wouldn''t work as soon as I saw how dark the thumbnail turned out. Live and learn. :-) Flash might have been cool, yeah. Thanks for the feedback.', '2009-09-09 20:49:25.000000', NULL, 0),
(5642504, 818617, 73564, '<td valign="top">Just awesome! Congrats on 1st!!</td>', 'Just awesome! Congrats on 1st!!', '2009-09-09 21:10:16.000000', NULL, 0),
(5642505, 817585, 73564, '<td valign="top">Very nicely presented, Congrats on 2nd place!</td>', 'Very nicely presented, Congrats on 2nd place!', '2009-09-09 21:10:40.000000', NULL, 0),
(5642507, 818771, 73564, '<td valign="top">Great shot....Love the tones, Congrats!</td>', 'Great shot....Love the tones, Congrats!', '2009-09-09 21:11:02.000000', NULL, 0),
(5642508, 818230, 73564, '<td valign="top">Neat!!! Congrats on 4th!</td>', 'Neat!!! Congrats on 4th!', '2009-09-09 21:11:16.000000', NULL, 0),
(5642511, 818000, 73564, '<td valign="top">Awesome clarity, great job!</td>', 'Awesome clarity, great job!', '2009-09-09 21:11:39.000000', NULL, 0),
(5642512, 818021, 73564, '<td valign="top">Neat image, well done, nice placing!</td>', 'Neat image, well done, nice placing!', '2009-09-09 21:12:04.000000', NULL, 0),
(5642535, 818045, 37845, '<td valign="top">I saw the lines, and liked the shot a lot. I gave you an 8, and feel that this shot is underrated. Beautiful shot though, congrats on the great capture.</td>', 'I saw the lines, and liked the shot a lot. I gave you an 8, and feel that this shot is underrated. Beautiful shot though, congrats on the great capture.', '2009-09-09 21:29:09.000000', NULL, 0),
(5642539, 817490, 37845, '<td valign="top">What a great shot.... where was it taken?</td>', 'What a great shot.... where was it taken?', '2009-09-09 21:30:14.000000', NULL, 0),
(5642557, 818399, 23484, '<td valign="top">Boy, the comments have been almost non existant lately.  I think this is a great shot for the challenge and very well composed. It''s just one of those shots that doesn''t "wow" the DPC voters.  Keep up the good work Nancy.</td>', 'Boy, the comments have been almost non existant lately.  I think this is a great shot for the challenge and very well composed. It''s just one of those shots that doesn''t "wow" the DPC voters.  Keep up the good work Nancy.', '2009-09-09 21:35:27.000000', NULL, 0),
(5642580, 818816, 7743, '<td valign="top">Challengewise I''d say the connection is average and that the image is more about the skyline than the lines in the water which is probably why the image got a fair number of low votes.<br/> <br/>That out of the way I think the scene is pretty but there is not really one thing for the eye to rest on as the main focal point.  The buildings could be interesting but are too far away to carry the image.  The reflection is interesting but to me, either not crisp enough to really draw my attention or blurry enough to create a more impressionistic image.  Also, some of the areas of the reflection are too bright and appear blown out.<br/><br/><i>Message edited by author 2009-09-09 20:56:55.</i></td>', 'Challengewise I''d say the connection is average and that the image is more about the skyline than the lines in the water which is probably why the image got a fair number of low votes. That out of the way I think the scene is pretty but there is not really one thing for the eye to rest on as the main focal point.  The buildings could be interesting but are too far away to carry the image.  The reflection is interesting but to me, either not crisp enough to really draw my attention or blurry enough to create a more impressionistic image.  Also, some of the areas of the reflection are too bright and appear blown out.', '2009-09-09 21:56:40.000000', '2009-09-09 21:56:55.000000', 0),
(5642581, 818617, 90495, '<td valign="top">Fantastic shot, a well deserved blue.</td>', 'Fantastic shot, a well deserved blue.', '2009-09-09 21:57:20.000000', NULL, 0),
(5642594, 818816, 83313, '<td valign="top">I gave it a 5. Composition is somewhat too centered for my preference. Not a lot of interest in the water, but it consumes half the frame. Moving the bridge and waterline down to about the lower third may have helped the comp. I also feel the golden tones are just overwhelming the shot. Perhaps a different WB would have brought out some other colors besides all that yellow.</td>', 'I gave it a 5. Composition is somewhat too centered for my preference. Not a lot of interest in the water, but it consumes half the frame. Moving the bridge and waterline down to about the lower third may have helped the comp. I also feel the golden tones are just overwhelming the shot. Perhaps a different WB would have brought out some other colors besides all that yellow.', '2009-09-09 22:10:20.000000', NULL, 0),
(5642595, 818816, 100301, '<td valign="top">portland is beautiful, my home city (even though I live in medford now).</td>', 'portland is beautiful, my home city (even though I live in medford now).', '2009-09-09 22:10:27.000000', NULL, 0),
(5642619, 817608, 67152, '<td valign="top">i quite like this one Judi - and I think having Kita in the image does add a bunch to break up the lines and create others.  My only nit is that I see some apparent oversharpening along the diagonals in the upper center of the image - but I can''t imagine giving this anything less than a 6 - even on a really grumpy day.</td>', 'i quite like this one Judi - and I think having Kita in the image does add a bunch to break up the lines and create others.  My only nit is that I see some apparent oversharpening along the diagonals in the upper center of the image - but I can''t imagine giving this anything less than a 6 - even on a really grumpy day.', '2009-09-09 22:33:58.000000', NULL, 0),
(5642628, 818816, 80859, '<td valign="top">i like your image a lot.  i gave it a 7.  i''m not a great commenter.  i don''t feel qualified to give a proper ''critique''.</td>', 'i like your image a lot.  i gave it a 7.  i''m not a great commenter.  i don''t feel qualified to give a proper ''critique''.', '2009-09-09 22:41:34.000000', NULL, 0),
(5642633, 817241, 67152, '<td valign="top">This shot clearly meets the challenge description, but i think it is missing a main component - a place for the viewer to focus, a subject to draw the eye.  The lines in focus are placed in a static location (centered) and the focus on those lines is not as crisp as it could be.</td>', 'This shot clearly meets the challenge description, but i think it is missing a main component - a place for the viewer to focus, a subject to draw the eye.  The lines in focus are placed in a static location (centered) and the focus on those lines is not as crisp as it could be.', '2009-09-09 22:45:37.000000', NULL, 0),
(5642637, 818449, 87305, '<td valign="top">46 seconds !! great picture,congratulations...</td>', '46 seconds !! great picture,congratulations...', '2009-09-09 22:48:27.000000', NULL, 0),
