(6108463, 818771, 73942, '<td valign="top">beautiful, one of the better brooklyn bridge shots i''ve seen</td>', 'beautiful, one of the better brooklyn bridge shots i''ve seen', '2010-07-29 11:10:35.000000', NULL, 0),
(6118387, 818824, 40718, '<td valign="top">I like doing shots like this, but have you noticed that even a few inches off the center of the image, or having the lens just off parallel will skew the shot.  I can see the arches naturally curve to the right eventually, but I also see that right away the spine of the arch isn''t perfectly vertical.  If you can get the camera positioned just right to have that straight up and down, I think it transforms the shot somewhat.</td>', 'I like doing shots like this, but have you noticed that even a few inches off the center of the image, or having the lens just off parallel will skew the shot.  I can see the arches naturally curve to the right eventually, but I also see that right away the spine of the arch isn''t perfectly vertical.  If you can get the camera positioned just right to have that straight up and down, I think it transforms the shot somewhat.', '2010-08-04 21:04:36.000000', NULL, 0),
(6279454, 817424, 11769, '<td valign="top">You have an amazing sense of color. Love it.</td>', 'You have an amazing sense of color. Love it.', '2011-01-11 00:47:17.000000', NULL, 0),
(6330921, 818230, 74559, '<td valign="top">Absolutely beautiful!</td>', 'Absolutely beautiful!', '2011-02-24 12:31:52.000000', NULL, 0),
(6450153, 817503, 12611, '<td valign="top">Good red-rust feel- impeccable composition-great depth- sacrificing only a bit of busyness in the center.</td>', 'Good red-rust feel- impeccable composition-great depth- sacrificing only a bit of busyness in the center.', '2011-06-22 10:06:03.000000', NULL, 0),
